sp_widget.client_script:
function($scope, $http, $timeout, $uibModal, $sce) {

  $scope.modalData = {};

  $scope.openModal = function(node) {
    var usersHtml = node.users ? $sce.trustAsHtml(node.users) : '';
    $scope.modalData = {
      name: node.name,
      title: node.title,
      desc: node.desc,
      users: usersHtml
    };

    $scope.modalInstance = $uibModal.open({
      templateUrl: 'modalTemplate',
      scope: $scope
    });
  };

  $scope.closeModal = function() {
    if ($scope.modalInstance) {
      $scope.modalInstance.close();
      $scope.modalInstance = null;
    }
  };

  function loadScript(src) {
    return new Promise(function(resolve, reject) {
      var script = document.createElement('script');
      script.src = src;
      script.onload = resolve;
      script.onerror = reject;
      document.head.appendChild(script);
    });
  }

  function loadAllScripts() {
    var scripts = [
      'https://code.highcharts.com/highcharts.js',
      'https://code.highcharts.com/modules/sankey.js',
      'https://code.highcharts.com/modules/organization.js',
      'https://code.highcharts.com/modules/exporting.js',
      'https://code.highcharts.com/modules/accessibility.js'
    ];

    var promise = Promise.resolve();
    for (var i = 0; i < scripts.length; i++) {
      (function(src) {
        promise = promise.then(function() {
          return loadScript(src);
        });
      })(scripts[i]);
    }
    return promise;
  }

  function initChart() {
    loadAllScripts().then(function() {

      Highcharts.setOptions({
        chart: {
          style: {
            fontFamily: 'Roboto Flex, sans-serif'
          }
        }
      });

      Highcharts.chart('container', {
        chart: {
          height: 800,
          inverted: true
        },
        title: {
          text: 'Organograma da Empresa'
        },
        series: [{
          type: 'organization',
          name: 'Organograma',
          keys: ['from', 'to'],
          data: $scope.data.links,
          nodes: $scope.data.nodes,
          colorByPoint: false,
          color: '#293273',
          borderColor: 'white',
          nodeWidth: 100,
          dataLabels: {
            color: 'white',
            style: {
              textOutline: 'none',
              fontWeight: 'bold'
            },
            formatter: function() {
              return this.point.desc || this.point.title || this.point.name;
            }
          },
          events: {
            click: function(event) {
              var node = event.point;
              $scope.openModal(node);
              $scope.$apply();
            }
          }
        }],
        tooltip: {
          enabled: false
        },
        exporting: {
          enabled: true,
          allowHTML: true,
          sourceWidth: 1000,
          sourceHeight: 800,
          buttons: {
            contextButton: {
              menuItems: ['printChart', 'viewFullscreen']
            }
          }
        }
      });

      // Aplicar cantos arredondados
      var rects = document.querySelectorAll('#container svg rect.highcharts-point');
      for (var i = 0; i < rects.length; i++) {
        rects[i].setAttribute('rx', '15');
        rects[i].setAttribute('ry', '15');
      }

    }).catch(function(e) {
      console.error('Erro ao carregar gráfico:', e);
    });
  }

  $timeout(function() {
    initChart();
  }, 1000);
}

sp_widget.css:
div, h3, h2, h1, h4 {
	 font-family: 'Roboto Flex', sans-serif;
}

sp_widget.link:
function link(scope, element, attrs, controller) {
angular.module('sn.$sp').directive('orgChart', function($compile) {
  return {
    scope: {
      node: '='
    },
    templateUrl: 'org-chart-template',
    link: function(scope, element) {
      $compile(element.contents())(scope);
    }
  };
});


}

sp_widget.script:
(function() {
  var nodes = [];
  var links = [];

  function fetchChildren(parentSysId, level) {
    var gr = new GlideRecord('cmn_department');
    gr.addQuery('u_nome_unidade_superior', parentSysId);
    gr.query();

    while (gr.next()) {
      var childSysId = gr.sys_id.toString();

      // Busca usuários
      var userGr = new GlideRecord('sys_user');
      userGr.addQuery('department', childSysId);
      userGr.query();

      var users = [];
      while (userGr.next()) {
        users.push(userGr.name + ' - ' + (userGr.title || 'Sem função'));
      }

      var color = '#293273';
      if (level === 0) color = '#808080';
      else if (level === 1) color = '#6CB4EE';

      nodes.push({
        id: childSysId,
        title: gr.getValue('u_sigla_unidade') || '',
        name: gr.name.toString(),
        desc: gr.getValue('description') || '',
        users: users.join('<br>'),
        color: color
      });

      links.push([parentSysId, childSysId]);

      fetchChildren(childSysId, level + 1);
    }
  }

  var rootSysId = '22a5b94487030690947032a70cbb35ae'; 
  var root = new GlideRecord('cmn_department');
  if (root.get(rootSysId)) {
    var userGr = new GlideRecord('sys_user');
    userGr.addQuery('department', rootSysId);
    userGr.query();

    var users = [];
    while (userGr.next()) {
      users.push(userGr.name + ' - ' + (userGr.title || 'Sem função'));
    }

    nodes.push({
      id: rootSysId,
      title: root.getValue('u_sigla_unidade') || '',
      name: root.name.toString(),
      desc: root.getValue('description') || '',
      users: users.join('<br>'),
      color: '#808080'
    });
  }

  fetchChildren(rootSysId, 1);

  data.links = links;
  data.nodes = nodes;
})();
